// ─── File: src/main/java/com/bank/hr/service/HrAnalyticsService.java ───
package com.bank.hr.service;

import com.bank.hr.dto.HrReport;
import com.bank.hr.model.Employee;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.*;
import java.util.stream.Collectors;

@Service
@Slf4j
public class HrAnalyticsService {

    private final List<Employee> employees = List.of(
        new Employee("E001", "Rajesh Kumar",    "TRADING",    "Mumbai",    35, "M", new BigDecimal("1200000")),
        new Employee("E002", "Priya Sharma",    "RISK",       "Mumbai",    28, "F", new BigDecimal("1000000")),
        new Employee("E003", "Amit Patel",      "TRADING",    "Delhi",     52, "M", new BigDecimal("1500000")),
        new Employee("E004", "Deepa Reddy",     "OPERATIONS", "Bangalore", 45, "F", new BigDecimal("900000")),
        new Employee("E005", "Vikram Singh",    "RISK",       "Mumbai",    55, "M", new BigDecimal("1800000")),
        new Employee("E006", "Neha Gupta",      "TRADING",    "Delhi",     32, "F", new BigDecimal("1100000")),
        new Employee("E007", "Suresh Iyer",     "OPERATIONS", "Chennai",   58, "M", new BigDecimal("1400000")),
        new Employee("E008", "Kavita Joshi",    "RISK",       "Bangalore", 41, "F", new BigDecimal("950000")),
        new Employee("E009", "Rohit Mehta",     "COMPLIANCE", "Mumbai",    48, "M", new BigDecimal("1300000")),
        new Employee("E010", "Anita Desai",     "COMPLIANCE", "Delhi",     37, "F", new BigDecimal("1050000"))
    );

    public HrReport generateReport() {

        // ═══ GROUP BY CITY — headcount per branch ═══
        Map<String, Long> byCity = employees.stream()
            .collect(Collectors.groupingBy(Employee::city, TreeMap::new, Collectors.counting()));
        log.info("Headcount by city: {}", byCity);

        // ═══ GROUP BY DEPARTMENT — team sizes ═══
        Map<String, Long> byDept = employees.stream()
            .collect(Collectors.groupingBy(Employee::department, TreeMap::new, Collectors.counting()));
        log.info("Headcount by department: {}", byDept);

        // ═══ FILTER: Mumbai branch employees ═══
        List<String> mumbaiEmps = employees.stream()
            .filter(e -> "Mumbai".equals(e.city()))
            .map(e -> e.empId() + " " + e.name() + " (" + e.department() + ")")
            .toList();
        log.info("Mumbai employees: {}", mumbaiEmps);

        // ═══ FILTER: Senior employees (age > 50) ═══
        List<String> seniors = employees.stream()
            .filter(e -> e.age() > 50)
            .sorted(Comparator.comparingInt(Employee::age).reversed())
            .map(e -> e.name() + " (age " + e.age() + ", " + e.department() + ")")
            .toList();
        log.info("Seniors above 50: {}", seniors);

        // ═══ COMBINED: filter Mumbai, THEN group by department ═══
        Map<String, List<String>> mumbaiByDept = employees.stream()
            .filter(e -> "Mumbai".equals(e.city()))
            .collect(Collectors.groupingBy(Employee::department,
                Collectors.mapping(Employee::name, Collectors.toList())));
        log.info("Mumbai by department: {}", mumbaiByDept);

        // ═══ GROUP BY AGE DECADE ═══
        Map<Integer, Long> byDecade = employees.stream()
            .collect(Collectors.groupingBy(
                e -> (e.age() / 10) * 10,  // 28→20, 35→30, 52→50
                TreeMap::new, Collectors.counting()));
        log.info("By age decade: {}", byDecade);

        return new HrReport(byCity, byDept, mumbaiEmps, seniors, mumbaiByDept, byDecade);
    }
}
