package com.bank.hr.service;

import com.bank.hr.model.Employee;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.*;
import java.util.stream.Collectors;
import static org.assertj.core.api.Assertions.*;

class EmployeeStreamTest {

    List<Employee> emps = List.of(
        new Employee("E1", "Rajesh", "TRADING", "Mumbai", 35, "M", BigDecimal.valueOf(1200000)),
        new Employee("E2", "Priya", "RISK", "Mumbai", 28, "F", BigDecimal.valueOf(1000000)),
        new Employee("E3", "Amit", "TRADING", "Delhi", 52, "M", BigDecimal.valueOf(1500000)),
        new Employee("E4", "Deepa", "RISK", "Bangalore", 45, "F", BigDecimal.valueOf(900000))
    );

    @Test
    void groupByCity() {
        Map<String, Long> byCity = emps.stream()
            .collect(Collectors.groupingBy(Employee::city, Collectors.counting()));
        assertThat(byCity).containsEntry("Mumbai", 2L).containsEntry("Delhi", 1L);
    }

    @Test
    void groupByDepartment() {
        Map<String, List<String>> namesByDept = emps.stream()
            .collect(Collectors.groupingBy(Employee::department,
                Collectors.mapping(Employee::name, Collectors.toList())));
        assertThat(namesByDept.get("TRADING")).containsExactly("Rajesh", "Amit");
    }

    @Test
    void filterByCity() {
        List<String> mumbai = emps.stream()
            .filter(e -> "Mumbai".equals(e.city()))
            .map(Employee::name).toList();
        assertThat(mumbai).containsExactly("Rajesh", "Priya");
    }

    @Test
    void filterByAge() {
        List<String> over50 = emps.stream()
            .filter(e -> e.age() > 50)
            .map(Employee::name).toList();
        assertThat(over50).containsExactly("Amit");
    }

    @Test
    void filterThenGroup() {
        Map<String, List<String>> mumbaiByDept = emps.stream()
            .filter(e -> "Mumbai".equals(e.city()))
            .collect(Collectors.groupingBy(Employee::department,
                Collectors.mapping(Employee::name, Collectors.toList())));
        assertThat(mumbaiByDept).containsEntry("TRADING", List.of("Rajesh"));
        assertThat(mumbaiByDept).containsEntry("RISK", List.of("Priya"));
    }

    @Test
    void groupByAgeDecade() {
        Map<Integer, Long> byDecade = emps.stream()
            .collect(Collectors.groupingBy(e -> (e.age()/10)*10, Collectors.counting()));
        assertThat(byDecade).containsEntry(20, 1L);  // Priya (28)
        assertThat(byDecade).containsEntry(30, 1L);  // Rajesh (35)
        assertThat(byDecade).containsEntry(50, 1L);  // Amit (52)
    }
}
